import java.util.*;

class Solution {
    public int singleNumber(int[] nums) {
        Map<Integer, Integer> map = new HashMap<>();
        for (int x : nums) map.merge(x, 1, Integer::sum);
        for (Map.Entry<Integer, Integer> e : map.entrySet()) {
            if (e.getValue() == 1) return e.getKey();
        }
        return -1;
    }
}

class Solution {
    public int singleNumber(int[] nums) {
        int[] cnt = new int[32];
        for (int x : nums) {
            for (int b = 0; b < 32; b++) {
                cnt[b] += (x >> b) & 1;
            }
        }

        int res = 0;
        for (int b = 0; b < 32; b++) {
            if (cnt[b] % 3 != 0) res |= 1 << b;
        }
        return res;
    }
}

class Solution {
    public int singleNumber(int[] nums) {
        int ones = 0;
        int twos = 0;
        for (int x : nums) {
            ones = (ones ^ x) & ~twos;
            twos = (twos ^ x) & ~ones;
        }
        return ones;
    }
}
